grid=[[4]*16 for _ in range(19)];
for r,c,v in [(2,2,1),(4,4,6),(4,14,1),(6,6,6),(7,14,6),(10,10,1),(15,2,6),(17,9,1)]: grid[r][c]=v
# connect all aligned same-color pairs at 45 degrees
for v in (1,6):
 pts=[(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==v]
 for i,(r,c) in enumerate(pts):
  for R,C in pts[i+1:]:
   dr,dc=R-r,C-c
   if abs(dr)==abs(dc) and dr:
    sr=1 if dr>0 else -1; sc=1 if dc>0 else -1
    for k in range(1,abs(dr)): grid[r+sr*k][c+sc*k]=v
print(grid)

# extend diagonal lines through 6 points across bounds
for r,c in [(4,4),(6,6),(7,14),(15,2)]:
 for dr,dc in [(1,1),(1,-1)]:
  # line invariant c - slope*r
  for rr in range(19):
   cc=c+(rr-r)*dc
   if 0<=cc<16 and grid[rr][cc]==4: grid[rr][cc]=6
print(grid)

g=[[4]*16 for _ in range(19)]
for r,c,v in [(2,2,1),(4,4,6),(4,14,1),(6,6,6),(7,14,6),(10,10,1),(15,2,6),(17,9,1)]: g[r][c]=v
for v in [1,6]:
 pts=[(r,c) for r in range(19) for c in range(16) if g[r][c]==v]
 for i,(r,c) in enumerate(pts):
  for R,C in pts[i+1:]:
   if abs(R-r)==abs(C-c) and R!=r:
    for k in range(1,abs(R-r)):
     g[r+(1 if R>r else -1)*k][c+(1 if C>c else -1)*k]=v
print(g)

